"use strict";
const pptxgen = require("pptxgenjs");

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.author = "TIOBE Analysis";
pres.title = "TIOBE Index March 2026";

// ── Palette ──────────────────────────────────────────────────────────────
const C = {
  dark:    "0F1B2D",   // near-black navy (title / conclusion bg)
  navy:    "1B3A5C",   // content header bg
  mid:     "1E4D7B",   // accent shapes
  teal:    "0D9488",   // gainer highlight
  red:     "DC2626",   // loser highlight
  gold:    "F59E0B",   // award / callout accent
  light:   "EFF6FF",   // slide background (content slides)
  white:   "FFFFFF",
  slate:   "64748B",
  label:   "334155",
  muted:   "94A3B8",
};

const FONT_H  = "Trebuchet MS";
const FONT_B  = "Calibri";

// ── Helpers ───────────────────────────────────────────────────────────────
function header(slide, title) {
  // Dark header bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.68,
    fill: { color: C.navy }, line: { color: C.navy }
  });
  // Accent strip
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0.68, w: 10, h: 0.04,
    fill: { color: C.teal }, line: { color: C.teal }
  });
  slide.addText(title, {
    x: 0.35, y: 0, w: 9.3, h: 0.68,
    fontSize: 16, fontFace: FONT_H, bold: true,
    color: C.white, valign: "middle", margin: 0
  });
}

function footer(slide) {
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 5.45, w: 10, h: 0.175,
    fill: { color: C.dark }, line: { color: C.dark }
  });
  slide.addText("Source: TIOBE Programming Community Index, March 2026  |  tiobe.com", {
    x: 0.35, y: 5.45, w: 9.3, h: 0.175,
    fontSize: 8, fontFace: FONT_B, color: C.muted,
    valign: "middle", margin: 0
  });
}

// ═══════════════════════════════════════════════════════════════════════════
// SLIDE 1 — TITLE
// ═══════════════════════════════════════════════════════════════════════════
{
  const slide = pres.addSlide();
  slide.background = { color: C.dark };

  // Left accent bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 0.18, h: 5.625,
    fill: { color: C.teal }, line: { color: C.teal }
  });

  // Decorative large "2026" watermark
  slide.addText("2026", {
    x: 5.5, y: 1.2, w: 4.3, h: 3,
    fontSize: 144, fontFace: FONT_H, bold: true,
    color: C.mid, transparency: 60,
    align: "center", valign: "middle", margin: 0
  });

  // Overline label
  slide.addText("TIOBE Programming Community Index  ·  March 2026", {
    x: 0.6, y: 1.05, w: 8.8, h: 0.35,
    fontSize: 11, fontFace: FONT_B, color: C.teal,
    bold: true, charSpacing: 2, margin: 0
  });

  // Main title
  slide.addText("TIOBE Index March 2026: How 20+ Search Engines Rank the World's Programming Languages", {
    x: 0.6, y: 1.45, w: 7.8, h: 2.1,
    fontSize: 30, fontFace: FONT_H, bold: true,
    color: C.white, valign: "top", margin: 0
  });

  // Subtitle / methodology blurb
  slide.addText(
    "Ratings are calculated from skilled-engineer demand, training courses, and third-party vendors — " +
    "measured via search-engine hit counts across Google, Bing, Wikipedia, Amazon, and 20+ other platforms.",
    {
      x: 0.6, y: 3.65, w: 7.8, h: 1.0,
      fontSize: 13, fontFace: FONT_B, color: C.muted,
      valign: "top", margin: 0
    }
  );

  // Bottom note
  slide.addText("Audience: Software Engineering Leads & Technology Strategists", {
    x: 0.6, y: 5.1, w: 9, h: 0.3,
    fontSize: 10, fontFace: FONT_B, color: C.slate,
    italic: true, margin: 0
  });
}

// ═══════════════════════════════════════════════════════════════════════════
// SLIDE 2 — TOP 20 RANKINGS
// ═══════════════════════════════════════════════════════════════════════════
{
  const slide = pres.addSlide();
  slide.background = { color: C.light };
  header(slide, "Python Holds #1 at 21.25% but C Surges to #2 with the Largest Gain");

  // Table data
  const tableRows = [
    // Header row
    [
      { text: "Mar 2026", options: { bold: true, color: C.white, fill: { color: C.navy }, fontSize: 9, align: "center" } },
      { text: "Mar 2025", options: { bold: true, color: C.white, fill: { color: C.navy }, fontSize: 9, align: "center" } },
      { text: "Language",  options: { bold: true, color: C.white, fill: { color: C.navy }, fontSize: 9, align: "left" } },
      { text: "Rating",   options: { bold: true, color: C.white, fill: { color: C.navy }, fontSize: 9, align: "center" } },
      { text: "YoY Δ",    options: { bold: true, color: C.white, fill: { color: C.navy }, fontSize: 9, align: "center" } },
    ]
  ];

  const rows = [
    [1, 1,  "Python",              "21.25%", "-2.59%"],
    [2, 4,  "C",                   "11.55%", "+2.02%"],
    [3, 2,  "C++",                 "8.18%",  "-2.90%"],
    [4, 3,  "Java",                "7.99%",  "-2.37%"],
    [5, 5,  "C#",                  "6.36%",  "+1.49%"],
    [6, 6,  "JavaScript",          "3.45%",  "-0.01%"],
    [7, 9,  "Visual Basic",        "2.50%",  "-0.02%"],
    [8, 8,  "SQL",                 "2.00%",  "-0.57%"],
    [9, 16, "R",                   "1.88%",  "+0.94%"],
    [10,10, "Delphi/Object Pascal","1.80%",  "-0.36%"],
    [11,24, "Perl",                "1.75%",  "+1.05%"],
    [12,12, "Scratch",             "1.63%",  "-0.03%"],
    [13,11, "Fortran",             "1.45%",  "-0.25%"],
    [14,14, "Rust",                "1.31%",  "+0.09%"],
    [15,15, "MATLAB",              "1.29%",  "+0.31%"],
    [16, 7, "Go",                  "1.29%",  "-1.49%"],
    [17,17, "Assembly language",   "1.29%",  "+0.42%"],
    [18,13, "PHP",                 "1.23%",  "-0.25%"],
    [19,18, "Ada",                 "1.10%",  "+0.25%"],
    [20,26, "Swift",               "1.04%",  "+0.44%"],
  ];

  for (const [cur, prev, lang, rating, yoy] of rows) {
    const isGainer = yoy.startsWith("+");
    const isLoser  = yoy.startsWith("-") && yoy !== "-0.01%" && yoy !== "-0.02%" && yoy !== "-0.03%";
    const yoyColor = isGainer ? C.teal : (isLoser ? C.red : C.slate);
    const rowFill  = cur % 2 === 0 ? "DBEAFE" : C.white;

    // Highlight big movers
    const bigGainer = isGainer && parseFloat(yoy) >= 0.9;
    const bigLoser  = isLoser  && parseFloat(yoy) <= -1.0;
    const langFill  = bigGainer ? "D1FAE5" : bigLoser ? "FEE2E2" : rowFill;

    tableRows.push([
      { text: String(cur),  options: { fontSize: 9, align: "center", fill: { color: rowFill }, color: C.label, bold: cur <= 4 } },
      { text: String(prev), options: { fontSize: 9, align: "center", fill: { color: rowFill }, color: C.slate } },
      { text: lang,         options: { fontSize: 9, align: "left",   fill: { color: langFill }, color: C.label, bold: cur <= 4 } },
      { text: rating,       options: { fontSize: 9, align: "center", fill: { color: rowFill }, color: C.label, bold: cur === 1 } },
      { text: yoy,          options: { fontSize: 9, align: "center", fill: { color: rowFill }, color: yoyColor, bold: bigGainer || bigLoser } },
    ]);
  }

  slide.addTable(tableRows, {
    x: 0.28, y: 0.82, w: 6.1, h: 4.5,
    colW: [0.6, 0.6, 1.95, 0.8, 0.8],
    border: { pt: 0.5, color: "CBD5E1" },
    rowH: 0.208,
  });

  // Right panel — callout stats
  // Python box
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.7, y: 0.82, w: 3.05, h: 1.55,
    fill: { color: C.navy }, line: { color: C.navy }
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.7, y: 0.82, w: 0.09, h: 1.55,
    fill: { color: C.gold }, line: { color: C.gold }
  });
  slide.addText("#1", {
    x: 6.85, y: 0.85, w: 2.8, h: 0.55,
    fontSize: 36, fontFace: FONT_H, bold: true, color: C.gold, margin: 0
  });
  slide.addText("Python  ·  21.25%", {
    x: 6.85, y: 1.35, w: 2.8, h: 0.3,
    fontSize: 12, fontFace: FONT_B, bold: true, color: C.white, margin: 0
  });
  slide.addText("YoY: −2.59 pp  (largest drop in top 5)", {
    x: 6.85, y: 1.63, w: 2.8, h: 0.3,
    fontSize: 9.5, fontFace: FONT_B, color: C.muted, margin: 0
  });

  // C surges box
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.7, y: 2.5, w: 3.05, h: 1.35,
    fill: { color: "EFF6FF" }, line: { color: "BFDBFE" }
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.7, y: 2.5, w: 0.09, h: 1.35,
    fill: { color: C.teal }, line: { color: C.teal }
  });
  slide.addText("C  ↑  #4 → #2", {
    x: 6.85, y: 2.55, w: 2.8, h: 0.38,
    fontSize: 15, fontFace: FONT_H, bold: true, color: C.mid, margin: 0
  });
  slide.addText("+2.02 pp  |  11.55%", {
    x: 6.85, y: 2.9, w: 2.8, h: 0.3,
    fontSize: 12, fontFace: FONT_B, color: C.teal, bold: true, margin: 0
  });
  slide.addText("Largest gain of any top-20 language", {
    x: 6.85, y: 3.2, w: 2.8, h: 0.3,
    fontSize: 9.5, fontFace: FONT_B, color: C.slate, margin: 0
  });

  // Concentration stat
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.7, y: 3.98, w: 3.05, h: 1.35,
    fill: { color: "FFF7ED" }, line: { color: "FED7AA" }
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.7, y: 3.98, w: 0.09, h: 1.35,
    fill: { color: C.gold }, line: { color: C.gold }
  });
  slide.addText("~49%", {
    x: 6.85, y: 4.02, w: 2.8, h: 0.55,
    fontSize: 36, fontFace: FONT_H, bold: true, color: C.gold, margin: 0
  });
  slide.addText("of index held by top 4 languages", {
    x: 6.85, y: 4.55, w: 2.8, h: 0.38,
    fontSize: 10, fontFace: FONT_B, color: C.label, margin: 0
  });
  slide.addText("Python · C · C++ · Java", {
    x: 6.85, y: 4.9, w: 2.8, h: 0.25,
    fontSize: 9, fontFace: FONT_B, color: C.slate, italic: true, margin: 0
  });

  footer(slide);
}

// ═══════════════════════════════════════════════════════════════════════════
// SLIDE 3 — BIGGEST MOVERS
// ═══════════════════════════════════════════════════════════════════════════
{
  const slide = pres.addSlide();
  slide.background = { color: C.light };
  header(slide, "Perl Jumps 13 Spots, R Climbs 7, and Go Drops 9 — The Biggest Rank Shifts of 2026");

  // Left half: GAINERS
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.28, y: 0.82, w: 4.5, h: 0.42,
    fill: { color: C.teal }, line: { color: C.teal }
  });
  slide.addText("▲  GAINERS", {
    x: 0.28, y: 0.82, w: 4.5, h: 0.42,
    fontSize: 13, fontFace: FONT_H, bold: true, color: C.white,
    align: "center", valign: "middle", margin: 0
  });

  const gainers = [
    { lang: "Perl",          from: 24, to: 11, delta: "+13 spots", pct: "+1.05%", note: "Entrenched in infrastructure & bioinformatics" },
    { lang: "R",             from: 16, to: 9,  delta: "+7 spots",  pct: "+0.94%", note: "Data science & statistics resurgence" },
    { lang: "Swift",         from: 26, to: 20, delta: "+6 spots",  pct: "+0.44%", note: "Apple platform growth; Kotlin retreats" },
    { lang: "C",             from: 4,  to: 2,  delta: "+2 spots",  pct: "+2.02%", note: "Largest absolute gain in top 20" },
    { lang: "C#",            from: 5,  to: 5,  delta: "held #5",   pct: "+1.49%", note: "2025 Language of the Year winner" },
  ];

  gainers.forEach(({ lang, from, to, delta, pct, note }, i) => {
    const y = 1.37 + i * 0.76;
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0.28, y, w: 4.5, h: 0.68,
      fill: { color: "D1FAE5" }, line: { color: "6EE7B7" }
    });
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0.28, y, w: 0.09, h: 0.68,
      fill: { color: C.teal }, line: { color: C.teal }
    });
    slide.addText(lang, {
      x: 0.45, y: y + 0.04, w: 1.7, h: 0.3,
      fontSize: 12, fontFace: FONT_H, bold: true, color: C.dark, margin: 0
    });
    slide.addText(`${from} → ${to}`, {
      x: 2.2, y: y + 0.04, w: 0.9, h: 0.3,
      fontSize: 11, fontFace: FONT_B, color: C.slate, margin: 0
    });
    slide.addText(delta + "  " + pct, {
      x: 3.1, y: y + 0.04, w: 1.55, h: 0.3,
      fontSize: 11, fontFace: FONT_B, bold: true, color: C.teal, margin: 0
    });
    slide.addText(note, {
      x: 0.45, y: y + 0.34, w: 4.2, h: 0.28,
      fontSize: 9, fontFace: FONT_B, color: C.slate, italic: true, margin: 0
    });
  });

  // Right half: LOSERS
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.22, y: 0.82, w: 4.5, h: 0.42,
    fill: { color: C.red }, line: { color: C.red }
  });
  slide.addText("▼  LOSERS", {
    x: 5.22, y: 0.82, w: 4.5, h: 0.42,
    fontSize: 13, fontFace: FONT_H, bold: true, color: C.white,
    align: "center", valign: "middle", margin: 0
  });

  const losers = [
    { lang: "Go",          from: 7,  to: 16, delta: "-9 spots",  pct: "-1.49%", note: "Sharpest absolute drop; possible Rust displacement" },
    { lang: "C++",         from: 2,  to: 3,  delta: "-1 spot",   pct: "-2.90%", note: "Largest % decline — biggest in top 5" },
    { lang: "Java",        from: 3,  to: 4,  delta: "-1 spot",   pct: "-2.37%", note: "Multi-year downtrend continues from peak ~25%" },
    { lang: "PHP",         from: 13, to: 18, delta: "-5 spots",  pct: "-0.25%", note: "Steady erosion as Python dominates web backends" },
    { lang: "Fortran",     from: 11, to: 13, delta: "-2 spots",  pct: "-0.25%", note: "Still top 15 despite age — HPC stronghold" },
  ];

  losers.forEach(({ lang, from, to, delta, pct, note }, i) => {
    const y = 1.37 + i * 0.76;
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 5.22, y, w: 4.5, h: 0.68,
      fill: { color: "FEE2E2" }, line: { color: "FCA5A5" }
    });
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 5.22, y, w: 0.09, h: 0.68,
      fill: { color: C.red }, line: { color: C.red }
    });
    slide.addText(lang, {
      x: 5.39, y: y + 0.04, w: 1.5, h: 0.3,
      fontSize: 12, fontFace: FONT_H, bold: true, color: C.dark, margin: 0
    });
    slide.addText(`${from} → ${to}`, {
      x: 6.94, y: y + 0.04, w: 0.9, h: 0.3,
      fontSize: 11, fontFace: FONT_B, color: C.slate, margin: 0
    });
    slide.addText(delta + "  " + pct, {
      x: 7.84, y: y + 0.04, w: 1.75, h: 0.3,
      fontSize: 11, fontFace: FONT_B, bold: true, color: C.red, margin: 0
    });
    slide.addText(note, {
      x: 5.39, y: y + 0.34, w: 4.2, h: 0.28,
      fontSize: 9, fontFace: FONT_B, color: C.slate, italic: true, margin: 0
    });
  });

  // Center divider line
  slide.addShape(pres.shapes.LINE, {
    x: 4.9, y: 0.82, w: 0, h: 4.6,
    line: { color: "CBD5E1", width: 1, dashType: "dash" }
  });

  footer(slide);
}

// ═══════════════════════════════════════════════════════════════════════════
// SLIDE 4 — HISTORICAL CONTEXT
// ═══════════════════════════════════════════════════════════════════════════
{
  const slide = pres.addSlide();
  slide.background = { color: C.light };
  header(slide, "From Lisp at #2 in 1986 to Python at #1 in 2026: How Language Rankings Shifted Over Time");

  // Long-term table (left panel)
  const years = ["1986","1991","1996","2001","2006","2011","2016","2021","2026"];
  const tableData = [
    [
      { text: "Language", options: { bold: true, color: C.white, fill: { color: C.navy }, fontSize: 8, align: "left" } },
      ...years.map(y => ({ text: y, options: { bold: true, color: C.white, fill: { color: C.navy }, fontSize: 8, align: "center" } }))
    ]
  ];

  const histRows = [
    ["Python", "-","-","17","26","8","7","5","3","1"],
    ["C",      "1","1","1","1","2","2","2","1","2"],
