// ═══════════════════════════════════════════════════════════════════════════
// SLIDE 3 — BIGGEST MOVERS
// ═══════════════════════════════════════════════════════════════════════════
{
  const slide = pres.addSlide();
  slide.background = { color: C.light };
  header(slide, "Perl Jumps 13 Spots, R Climbs 7, and Go Drops 9 — The Biggest Rank Shifts of 2026");

  // Left half: GAINERS
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.28, y: 0.82, w: 4.5, h: 0.42,
    fill: { color: C.teal }, line: { color: C.teal }
  });
  slide.addText("▲  GAINERS", {
    x: 0.28, y: 0.82, w: 4.5, h: 0.42,
    fontSize: 13, fontFace: FONT_H, bold: true, color: C.white,
