  });

  const gainers = [
    { lang: "Perl",          from: 24, to: 11, delta: "+13 spots", pct: "+1.05%", note: "Entrenched in infrastructure & bioinformatics" },
    { lang: "R",             from: 16, to: 9,  delta: "+7 spots",  pct: "+0.94%", note: "Data science & statistics resurgence" },
    { lang: "Swift",         from: 26, to: 20, delta: "+6 spots",  pct: "+0.44%", note: "Apple platform growth; Kotlin retreats" },
    { lang: "C",             from: 4,  to: 2,  delta: "+2 spots",  pct: "+2.02%", note: "Largest absolute gain in top 20" },
