    slide.addText(lang, {
      x: 0.45, y: y + 0.04, w: 1.7, h: 0.3,
      fontSize: 12, fontFace: FONT_H, bold: true, color: C.dark, margin: 0
    });
    slide.addText(`${from} → ${to}`, {
      x: 2.2, y: y + 0.04, w: 0.9, h: 0.3,
      fontSize: 11, fontFace: FONT_B, color: C.slate, margin: 0
    });
    slide.addText(delta + "  " + pct, {
      x: 3.1, y: y + 0.04, w: 1.55, h: 0.3,
      fontSize: 11, fontFace: FONT_B, bold: true, color: C.teal, margin: 0
    });
    slide.addText(note, {
      x: 0.45, y: y + 0.34, w: 4.2, h: 0.28,
      fontSize: 9, fontFace: FONT_B, color: C.slate, italic: true, margin: 0
