    slide.addText(delta + "  " + pct, {
      x: 7.84, y: y + 0.04, w: 1.75, h: 0.3,
      fontSize: 11, fontFace: FONT_B, bold: true, color: C.red, margin: 0
    });
    slide.addText(note, {
      x: 5.39, y: y + 0.34, w: 4.2, h: 0.28,
