// ═══════════════════════════════════════════════════════════════════════════
// SLIDE 4 — HISTORICAL CONTEXT
// ═══════════════════════════════════════════════════════════════════════════
{
  const slide = pres.addSlide();
  slide.background = { color: C.light };
  header(slide, "From Lisp at #2 in 1986 to Python at #1 in 2026: How Language Rankings Shifted Over Time");

  // Long-term table (left panel)
  const years = ["1986","1991","1996","2001","2006","2011","2016","2021","2026"];
  const tableData = [
    [
      { text: "Language", options: { bold: true, color: C.white, fill: { color: C.navy }, fontSize: 8, align: "left" } },
      ...years.map(y => ({ text: y, options: { bold: true, color: C.white, fill: { color: C.navy }, fontSize: 8, align: "center" } }))
    ]
  ];

  const histRows = [
    ["Python", "-","-","17","26","8","7","5","3","1"],
    ["C",      "1","1","1","1","2","2","2","1","2"],
    ["C++",    "9","2","2","2","3","3","3","4","3"],
    ["Java",   "-","-","31","3","1","1","1","2","4"],
    ["C#",     "-","-","-","11","7","5","4","5","5"],
    ["JavaScript","-","-","33","8","10","10","8","7","6"],
    ["Go",     "-","-","-","-","-","16","60","11","10(16)"],
    ["Ada",    "3","10","6","18","16","22","25","36","14(19)"],
    ["Lisp",   "2","4","8","19","14","13","26","34","26"],
  ];

  histRows.forEach(([lang, ...vals], i) => {
    const rowFill = i % 2 === 0 ? C.white : "EFF6FF";
    // highlight python 2026 cell
    const cells = vals.map((v, j) => {
      let fill = { color: rowFill };
      let col = C.label;
      let bold = false;
      if (lang === "Python" && j === 8) { fill = { color: "D1FAE5" }; col = "065F46"; bold = true; }
      if (lang === "C"      && j === 8) { fill = { color: "DBEAFE" }; col = C.mid;   bold = true; }
      if (lang === "Lisp"   && j === 0) { fill = { color: "FEE2E2" }; col = "991B1B"; bold = true; }
      if (v === "-") col = C.muted;
      return { text: v, options: { fontSize: 8, align: "center", fill, color: col, bold } };
    });
    tableData.push([
      { text: lang, options: { fontSize: 8, align: "left", fill: { color: rowFill }, color: C.label, bold: ["Python","C"].includes(lang) } },
      ...cells
    ]);
  });

  slide.addTable(tableData, {
    x: 0.28, y: 0.82, w: 5.8,
    colW: [1.1, 0.52, 0.52, 0.52, 0.52, 0.52, 0.52, 0.52, 0.52, 0.52],
    border: { pt: 0.5, color: "CBD5E1" },
    rowH: 0.36,
  });

  // Right panel — key insight callouts
  const insights = [
    { icon: "★", color: C.teal,  title: "Python: 0 → #1 in 25 years", body: "Unranked before 1991. Entered top-30 by 2001. Took until post-2018 to reach #1." },
    { icon: "↓", color: C.red,   title: "Java's long decline",          body: "Dominated 2005–2018 at 25%+. Now below 8% — the steepest top-4 fall." },
    { icon: "⚓", color: C.gold,  title: "C: only constant in 40 years", body: "The sole language in the top 2 across all nine measurement points since 1986." },
    { icon: "▾", color: C.slate, title: "Lisp & Ada: four-decade fall",  body: "Lisp was #2 in 1986, now #26. Ada peaked at #3 in 1986, now #14." },
  ];

  insights.forEach(({ icon, color, title, body }, i) => {
    const y = 0.88 + i * 1.12;
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 6.28, y, w: 3.44, h: 0.98,
      fill: { color: C.white }, line: { color: "E2E8F0" },
      shadow: { type: "outer", blur: 4, offset: 1, angle: 135, color: "000000", opacity: 0.08 }
    });
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 6.28, y, w: 0.09, h: 0.98,
      fill: { color: color }, line: { color: color }
    });
    slide.addText(icon, {
      x: 6.42, y: y + 0.08, w: 0.38, h: 0.38,
      fontSize: 18, fontFace: FONT_H, bold: true, color: color, margin: 0
    });
    slide.addText(title, {
      x: 6.82, y: y + 0.07, w: 2.75, h: 0.3,
      fontSize: 10.5, fontFace: FONT_H, bold: true, color: C.dark, margin: 0
    });
    slide.addText(body, {
      x: 6.82, y: y + 0.38, w: 2.75, h: 0.52,
      fontSize: 9, fontFace: FONT_B, color: C.slate, margin: 0
    });
  });

  // Source note
  slide.addText("Table: rank positions at 5-year intervals, 1986–2026. Go '2026' rank shown as current (16) vs. table snapshot.", {
    x: 0.28, y: 5.15, w: 9.5, h: 0.22,
    fontSize: 8, fontFace: FONT_B, color: C.muted, italic: true, margin: 0
  });

  footer(slide);
}

// ═══════════════════════════════════════════════════════════════════════════
// SLIDE 5 — HALL OF FAME
// ═══════════════════════════════════════════════════════════════════════════
{
  const slide = pres.addSlide();
  slide.background = { color: C.dark };

  // Header — dark theme
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.04,
    fill: { color: C.gold }, line: { color: C.gold }
  });

  slide.addText("Python Wins Language of the Year 6 Times — More Than Any Other Language", {
    x: 0.4, y: 0.18, w: 9.2, h: 0.72,
    fontSize: 18, fontFace: FONT_H, bold: true,
    color: C.white, valign: "middle", margin: 0
  });

  // Awards grid — 2016–2025 (skipping 2017 not available)
  const awards = [
    { year: "2025", lang: "C#",     color: "6366F1", note: "2nd win in 3 years" },
    { year: "2024", lang: "Python", color: C.teal,  note: "6th all-time win" },
    { year: "2023", lang: "C#",     color: "6366F1", note: ".NET ecosystem growth" },
    { year: "2022", lang: "C++",    color: "F97316", note: "Systems programming surge" },
    { year: "2021", lang: "Python", color: C.teal,  note: "5th all-time win" },
    { year: "2020", lang: "Python", color: C.teal,  note: "4th all-time win" },
    { year: "2019", lang: "C",      color: "38BDF8", note: "Steady resurgence" },
    { year: "2018", lang: "Python", color: C.teal,  note: "3rd all-time win" },
    { year: "2016", lang: "Go",     color: "A3E635", note: "Preceded its 2026 decline" },
  ];

  // 3-column grid
  const cols = 3;
  const cardW = 2.8, cardH = 1.1;
  const startX = 0.35, startY = 1.08, gapX = 0.2, gapY = 0.18;

  awards.forEach(({ year, lang, color, note }, i) => {
    const col = i % cols;
    const row = Math.floor(i / cols);
    const x = startX + col * (cardW + gapX);
    const y = startY + row * (cardH + gapY);

    slide.addShape(pres.shapes.RECTANGLE, {
      x, y, w: cardW, h: cardH,
      fill: { color: "1B2E47" }, line: { color: "2D4A6E" }
    });
    // Top accent strip
    slide.addShape(pres.shapes.RECTANGLE, {
      x, y, w: cardW, h: 0.055,
      fill: { color: color }, line: { color: color }
    });
    slide.addText(year, {
      x: x + 0.15, y: y + 0.1, w: 0.75, h: 0.35,
      fontSize: 13, fontFace: FONT_H, color: C.muted, bold: false, margin: 0
    });
    slide.addText(lang, {
      x: x + 0.15, y: y + 0.42, w: cardW - 0.3, h: 0.4,
      fontSize: 19, fontFace: FONT_H, bold: true, color: color, margin: 0
    });
    slide.addText(note, {
      x: x + 0.15, y: y + 0.82, w: cardW - 0.3, h: 0.24,
      fontSize: 9, fontFace: FONT_B, color: C.muted, italic: true, margin: 0
    });
  });

  // Right summary callout
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 9.22, y: 1.08, w: 0.58, h: 4.1,
    fill: { color: "1B2E47" }, line: { color: "2D4A6E" }
  });

  // Python stat
  slide.addText("Python: 6×", {
    x: 0.35, y: 4.88, w: 4.2, h: 0.28,
    fontSize: 10, fontFace: FONT_B, color: C.teal, bold: true, margin: 0
  });
  slide.addText("wins (2007, 2010, 2018, 2020, 2021, 2024) — most of any language", {
    x: 4.0, y: 4.88, w: 5.1, h: 0.28,
    fontSize: 10, fontFace: FONT_B, color: C.muted, margin: 0
  });

  // Note on 2017
  slide.addText("Note: 2017 winner not available in source data.", {
    x: 0.35, y: 5.2, w: 9, h: 0.22,
    fontSize: 8.5, fontFace: FONT_B, color: C.slate, italic: true, margin: 0
  });

  // Dark footer
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 5.45, w: 10, h: 0.175,
    fill: { color: "080E18" }, line: { color: "080E18" }
  });
  slide.addText("Source: TIOBE Programming Community Index, March 2026  |  tiobe.com", {
    x: 0.35, y: 5.45, w: 9.3, h: 0.175,
    fontSize: 8, fontFace: FONT_B, color: "3A5070",
    valign: "middle", margin: 0
  });
}

// ═══════════════════════════════════════════════════════════════════════════
// SLIDE 6 — TAKEAWAYS
// ═══════════════════════════════════════════════════════════════════════════
{
  const slide = pres.addSlide();
  slide.background = { color: C.dark };

  // Top gold bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.06,
    fill: { color: C.gold }, line: { color: C.gold }
  });

  slide.addText("The Top 4 Languages Hold 49% of the Index:", {
    x: 0.4, y: 0.12, w: 9.2, h: 0.45,
    fontSize: 20, fontFace: FONT_H, bold: true,
    color: C.white, valign: "middle", margin: 0
  });
  slide.addText("What This Means for Your Tech Stack", {
    x: 0.4, y: 0.54, w: 9.2, h: 0.34,
    fontSize: 15, fontFace: FONT_B, color: C.muted,
    valign: "middle", margin: 0
  });

  const takeaways = [
    {
      num: "01",
      color: C.teal,
      title: "Python leads — but watch the trajectory",
      body: "At 21.25%, Python is unchallenged. Yet its -2.59 pp drop is the largest in the top 5. C is closing the gap. Hiring and training pipelines are safe today; re-evaluate in 12–18 months."
    },
    {
      num: "02",
      color: "38BDF8",
      title: "C's resurgence is real — implications for embedded & systems",
      body: "C gained +2.02 pp and climbed from 4th to 2nd. For teams in embedded systems, IoT, or OS development, C expertise is increasingly strategic."
    },
    {
      num: "03",
      color: C.gold,
      title: "Legacy languages aren't dead — they're resilient",
      body: "Perl (+13 ranks), R (+7 ranks), and Fortran (still top 15) serve entrenched communities in bioinformatics, data science, and HPC. Don't deprecate internal expertise prematurely."
    },
    {
      num: "04",
      color: C.red,
      title: "Go's 9-rank freefall demands a re-assessment",
      body: "Go dropped from 7th to 16th (-1.49 pp), possibly displaced by Rust in systems programming. Teams evaluating Go for new services should weigh this trend against current talent depth."
    },
    {
      num: "05",
      color: "A78BFA",
      title: "Concentration risk: 49% held by 4 languages",
      body: "Python, C, C++, and Java together hold ~49% of the index. Diverse-language organizations may enjoy lower bus-factor risk. Single-language bets amplify both upside and exposure."
    },
  ];

  const cardW = 4.5, cardH = 0.88;
  const positions = [
    [0.28, 1.05], [5.22, 1.05],
    [0.28, 2.06], [5.22, 2.06],
    [0.28, 3.07]
  ];

  takeaways.forEach(({ num, color, title, body }, i) => {
    const [x, y] = positions[i];
    const w = i === 4 ? 9.44 : cardW;

    slide.addShape(pres.shapes.RECTANGLE, {
      x, y, w, h: cardH,
      fill: { color: "132035" }, line: { color: "1E3A55" }
    });
    slide.addShape(pres.shapes.RECTANGLE, {
      x, y, w: 0.09, h: cardH,
      fill: { color: color }, line: { color: color }
    });
    slide.addText(num, {
      x: x + 0.18, y: y + 0.06, w: 0.42, h: 0.36,
      fontSize: 14, fontFace: FONT_H, bold: true, color: color, margin: 0
    });
    slide.addText(title, {
      x: x + 0.62, y: y + 0.06, w: w - 0.72, h: 0.3,
      fontSize: 11, fontFace: FONT_H, bold: true, color: C.white, margin: 0
    });
    slide.addText(body, {
      x: x + 0.62, y: y + 0.37, w: w - 0.72, h: 0.46,
      fontSize: 9.5, fontFace: FONT_B, color: C.muted, margin: 0
    });
  });

  // CTA / attribution bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 4.08, w: 10, h: 0.68,
    fill: { color: "0A1628" }, line: { color: "0A1628" }
  });
  slide.addText("Data: TIOBE Index March 2026  ·  Next update: April 2026  ·  Decisions should combine TIOBE trends with GitHub/Stack Overflow activity data.", {
    x: 0.4, y: 4.14, w: 9.2, h: 0.56,
