"use strict";
const pptxgen = require("pptxgenjs");

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.author = "TIOBE Analysis";
pres.title = "TIOBE Index March 2026";

// ── Palette ──────────────────────────────────────────────────────────────
const C = {
  dark:    "0F1B2D",   // near-black navy (title / conclusion bg)
  navy:    "1B3A5C",   // content header bg
  mid:     "1E4D7B",   // accent shapes
  teal:    "0D9488",   // gainer highlight
