      if (v === "-") col = C.muted;
      return { text: v, options: { fontSize: 8, align: "center", fill, color: col, bold } };
    });
    tableData.push([
      { text: lang, options: { fontSize: 8, align: "left", fill: { color: rowFill }, color: C.label, bold: ["Python","C"].includes(lang) } },
