[metadata] {"type": "update", "filePath": "/app/generate_deck.js", "content": ""use strict";
const pptxgen = require("pptxgenjs");

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.author = "TIOBE Analysis";
pres.title = "TIOBE Index March 2026";

// ── Palette ──────────────────────────────────────────────────────────────
const C = {
  dark:    "0F1B2D",
  navy:    "1B3A5C",
  mid:     "1E4D7B",
  teal:    "0D9488",
  red:     "DC2626",
  gold:    "F59E0B",
  light:   "EFF6FF",
  white:   "FFFFFF",
  slate:   "64748B",
  label:   "334155",
  muted:   "94A3B8",
};

const FONT_H = "Trebuchet MS";
const FONT_B = "Calibri";

function header(slide, title) {
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.72,
    fill: { color: C.navy }, line: { color: C.navy }
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0.72, w: 10, h: 0.04,
    fill: { color: C.teal }, line: { color: C.teal }
  });
  slide.addText(title, {
    x: 0.35, y: 0, w: 9.3, h: 0.72,
    fontSize: 14.5, fontFace: FONT_H, bold: true,
    color: C.white, valign: "middle", margin: 0
  });
}

function footer(slide) {
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 5.45, w: 10, h: 0.175,
    fill: { color: C.dark }, line: { color: C.dark }
  });
  slide.addText("Source: TIOBE Programming Community Index, March 2026  |  tiobe.com", {
    x: 0.35, y: 5.45, w: 9.3, h: 0.175,
    fontSize: 8, fontFace: FONT_B, color: "6B8BAF",
    valign: "middle", margin: 0
  });
}

// ═══════════════════════════════════════════════════════════════════════════
// SLIDE 1 — TITLE
// ═══════════════════════════════════════════════════════════════════════════
{
  const slide = pres.addSlide();
  slide.background = { color: C.dark };

  // Left accent bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 0.18, h: 5.625,
    fill: { color: C.teal }, line: { color: C.teal }
  });

  // Decorative watermark — pushed right so it doesn't overlap main text
  slide.addText("2026", {
    x: 5.8, y: 0.8, w: 4.0, h: 3.2,
    fontSize: 148, fontFace: FONT_H, bold: true,
    color: "1E4D7B", transparency: 55,
    align: "center", valign: "middle", margin: 0
  });

  // Overline
  slide.addText("TIOBE PROGRAMMING COMMUNITY INDEX  ·  MARCH 2026", {
    x: 0.6, y: 0.8, w: 8.8, h: 0.35,
    fontSize: 10.5, fontFace: FONT_B, color: C.teal,
    bold: true, charSpacing: 2, margin: 0
  });

  // Main title
  slide.addText(
    "TIOBE Index March 2026:\nHow 20+ Search Engines Rank the World's Programming Languages",
    {
      x: 0.6, y: 1.22, w: 7.6, h: 2.1,
      fontSize: 29, fontFace: FONT_H, bold: true,
      color: C.white, valign: "top", margin: 0
    }
  );

  // Methodology body
  slide.addText(
    "Ratings are calculated from skilled-engineer demand, training courses, and third-party vendors — " +
    "measured via search-engine hit counts across Google, Bing, Wikipedia, Amazon, and 20+ other platforms.",
    {
      x: 0.6, y: 3.5, w: 7.6, h: 1.0,
      fontSize: 12.5, fontFace: FONT_B, color: "A8BFDA",
      valign: "top", margin: 0
    }
  );

  // Audience byline (no "Audience:" label)
  slide.addText("For Software Engineering Leads & Technology Strategists", {
    x: 0.6, y: 4.85, w: 9, h: 0.3,
    fontSize: 10, fontFace: FONT_B, color: C.slate,
    italic: true, margin: 0
  });
}

// ═══════════════════════════════════════════════════════════════════════════
// SLIDE 2 — TOP 20 RANKINGS
// ═══════════════════════════════════════════════════════════════════════════
{
  const slide = pres.addSlide();
  slide.background = { color: C.light };
  header(slide, "Python Holds #1 at 21.25% but C Surges to #2 with the Largest Gain");

  const tableRows = [
    [
      { text: "Mar 2026", options: { bold: true, color: C.white, fill: { color: C.navy }, fontSize: 8.5, align: "center" } },
      { text: "Mar 2025", options: { bold: true, color: C.white, fill: { color: C.navy }, fontSize: 8.5, align: "center" } },
      { text: "Language", options: { bold: true, color: C.white, fill: { color: C.navy }, fontSize: 8.5, align: "left" } },
      { text: "Rating",   options: { bold: true, color: C.white, fill: { color: C.navy }, fontSize: 8.5, align: "center" } },
      { text: "YoY (pp)", options: { bold: true, color: C.white, fill: { color: C.navy }, fontSize: 8.5, align: "center" } },
    ]
  ];

  const rows = [
    [1, 1,  "Python",               "21.25%", "-2.59"],
    [2, 4,  "C",                    "11.55%", "+2.02"],
    [3, 2,  "C++",                  "8.18%",  "-2.90"],
    [4, 3,  "Java",                 "7.99%",  "-2.37"],
    [5, 5,  "C#",                   "6.36%",  "+1.49"],
    [6, 6,  "JavaScript",           "3.45%",  "-0.01"],
    [7, 9,  "Visual Basic",         "2.50%",  "-0.02"],
    [8, 8,  "SQL",                  "2.00%",  "-0.57"],
    [9, 16, "R",                    "1.88%",  "+0.94"],
    [10,10, "Delphi/Obj. Pascal",   "1.80%",  "-0.36"],
    [11,24, "Perl",                 "1.75%",  "+1.05"],
    [12,12, "Scratch",              "1.63%",  "-0.03"],
    [13,11, "Fortran",              "1.45%",  "-0.25"],
    [14,14, "Rust",                 "1.31%",  "+0.09"],
    [15,15, "MATLAB",               "1.29%",  "+0.31"],
    [16, 7, "Go",                   "1.29%",  "-1.49"],
    [17,17, "Assembly",             "1.29%",  "+0.42"],
    [18,13, "PHP",                  "1.23%",  "-0.25"],
    [19,18, "Ada",                  "1.10%",  "+0.25"],
    [20,26, "Swift",                "1.04%",  "+0.44"],
  ];

  for (const [cur, prev, lang, rating, yoy] of rows) {
    const val = parseFloat(yoy);
    const isGainer = val > 0;
    const isLoser  = val < -0.1;
    const yoyColor = isGainer ? "065F46" : (isLoser ? "991B1B" : C.slate);
    const rowFill  = cur % 2 === 0 ? "DBEAFE" : C.white;
    const bigGainer = isGainer && val >= 0.9;
    const bigLoser  = isLoser  && val <= -1.0;
    const langFill  = bigGainer ? "D1FAE5" : bigLoser ? "FEE2E2" : rowFill;

    tableRows.push([
      { text: String(cur),  options: { fontSize: 8.5, align: "center", fill: { color: rowFill }, color: C.label, bold: cur <= 4 } },
      { text: String(prev), options: { fontSize: 8.5, align: "center", fill: { color: rowFill }, color: C.slate } },
      { text: lang,         options: { fontSize: 8.5, align: "left",   fill: { color: langFill }, color: C.label, bold: cur <= 4 } },
      { text: rating,       options: { fontSize: 8.5, align: "center", fill: { color: rowFill }, color: C.label, bold: cur === 1 } },
      { text: (val > 0 ? "+" : "") + yoy, options: { fontSize: 8.5, align: "center", fill: { color: rowFill }, color: yoyColor, bold: bigGainer || bigLoser } },
    ]);
  }

  slide.addTable(tableRows, {
    x: 0.28, y: 0.86, w: 6.1,
    colW: [0.6, 0.6, 2.0, 0.8, 0.82],
    border: { pt: 0.5, color: "CBD5E1" },
    rowH: 0.22,
  });

  // Right panel callouts — pushed down to leave footer gap
  // Python box
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.68, y: 0.86, w: 3.04, h: 1.38,
    fill: { color: C.navy }, line: { color: C.navy }
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.68, y: 0.86, w: 0.09, h: 1.38,
    fill: { color: C.gold }, line: { color: C.gold }
  });
  slide.addText("#1 Python", {
    x: 6.85, y: 0.92, w: 2.8, h: 0.45,
    fontSize: 26, fontFace: FONT_H, bold: true, color: C.gold, margin: 0
  });
  slide.addText("21.25%  |  YoY: −2.59 pp", {
    x: 6.85, y: 1.35, w: 2.8, h: 0.28,
    fontSize: 11, fontFace: FONT_B, color: C.white, margin: 0
  });
  slide.addText("Largest drop among the top 5", {
    x: 6.85, y: 1.6, w: 2.8, h: 0.22,
    fontSize: 9, fontFace: FONT_B, color: C.muted, margin: 0
  });

  // C surges box
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.68, y: 2.36, w: 3.04, h: 1.38,
    fill: { color: "EFF6FF" }, line: { color: "BFDBFE" }
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.68, y: 2.36, w: 0.09, h: 1.38,
    fill: { color: C.teal }, line: { color: C.teal }
  });
  slide.addText("C  ↑ #4 → #2", {
    x: 6.85, y: 2.42, w: 2.8, h: 0.38,
    fontSize: 18, fontFace: FONT_H, bold: true, color: C.mid, margin: 0
  });
  slide.addText("+2.02 pp  |  11.55%", {
    x: 6.85, y: 2.78, w: 2.8, h: 0.28,
    fontSize: 12, fontFace: FONT_B, color: C.teal, bold: true, margin: 0
  });
  slide.addText("Largest absolute gain in top 20", {
    x: 6.85, y: 3.04, w: 2.8, h: 0.22,
    fontSize: 9.5, fontFace: FONT_B, color: C.slate, margin: 0
  });
  slide.addText("C has closed the gap from 4th to 2nd in one year", {
    x: 6.85, y: 3.24, w: 2.8, h: 0.28,
    fontSize: 9, fontFace: FONT_B, color: C.slate, italic: true, margin: 0
  });

  // Concentration stat
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.68, y: 3.86, w: 3.04, h: 1.45,
    fill: { color: "FFF7ED" }, line: { color: "FED7AA" }
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.68, y: 3.86, w: 0.09, h: 1.45,
    fill: { color: C.gold }, line: { color: C.gold }
  });
  slide.addText("~49%", {
    x: 6.85, y: 3.92, w: 2.8, h: 0.55,
    fontSize: 38, fontFace: FONT_H, bold: true, color: C.gold, margin: 0
  });
  slide.addText("of the index held by just 4 languages", {
    x: 6.85, y: 4.45, w: 2.8, h: 0.28,
    fontSize: 10, fontFace: FONT_B, color: C.label, margin: 0
  });
  slide.addText("Python  ·  C  ·  C++  ·  Java", {
    x: 6.85, y: 4.73, w: 2.8, h: 0.28,
    fontSize: 10, fontFace: FONT_B, color: C.slate, bold: true, margin: 0
  });

  // Table note
  slide.addText("pp = percentage points YoY change. Green/red rows = biggest rank movers.", {
    x: 0.28, y: 5.28, w: 6.1, h: 0.18,
    fontSize: 7.5, fontFace: FONT_B, color: C.slate, italic: true, margin: 0
  });

  footer(slide);
}

// ═══════════════════════════════════════════════════════════════════════════
// SLIDE 3 — BIGGEST MOVERS
// ═══════════════════════════════════════════════════════════════════════════
{
  const slide = pres.addSlide();
  slide.background = { color: C.light };
  header(slide, "Perl Jumps 13 Spots, R Climbs 7, and Go Drops 9 — The Biggest Rank Shifts of 2026");

  // GAINERS header
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.28, y: 0.86, w: 4.5, h: 0.38,
    fill: { color: C.teal }, line: { color: C.teal }
  });
  slide.addText("GAINERS", {
    x: 0.28, y: 0.86, w: 4.5, h: 0.38,
    fontSize: 12, fontFace: FONT_H, bold: true, color: C.white,
    align: "center", valign: "middle", margin: 0
  });

  // LOSERS header
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.22, y: 0.86, w: 4.5, h: 0.38,
    fill: { color: C.red }, line: { color: C.red }
  });
  slide.addText("LOSERS", {
    x: 5.22, y: 0.86, w: 4.5, h: 0.38,
    fontSize: 12, fontFace: FONT_H, bold: true, color: C.white,
    align: "center", valign: "middle", margin: 0
  });

  const gainers = [
    { lang: "Perl",   from: 24, to: 11, delta: "+13 spots", pct: "+1.05 pp", note: "Bioinformatics & infrastructure — entrenched communities" },
    { lang: "R",      from: 16, to: 9,  delta: "+7 spots",  pct: "+0.94 pp", note: "Data science & statistics resurgence" },
    { lang: "Swift",  from: 26, to: 20, delta: "+6 spots",  pct: "+0.44 pp", note: "Apple platform growth; Kotlin retreats to #22" },
    { lang: "C",      from: 4,  to: 2,  delta: "+2 spots",  pct: "+2.02 pp", note: "Largest absolute rating gain of any language" },
  ];

  gainers.forEach(({ lang, from, to, delta, pct, note }, i) => {
    const y = 1.35 + i * 0.95;
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0.28, y, w: 4.5, h: 0.85,
      fill: { color: "D1FAE5" }, line: { color: "6EE7B7" }
    });
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0.28, y, w: 0.09, h: 0.85,
      fill: { color: C.teal }, line: { color: C.teal }
    });
    slide.addText(lang, {
      x: 0.45, y: y + 0.07, w: 1.4, h: 0.3,
      fontSize: 13, fontFace: FONT_H, bold: true, color: "064E3B", margin: 0
    });
    slide.addText(`${from} → ${to}`, {
      x: 1.9, y: y + 0.07, w: 0.85, h: 0.3,
      fontSize: 11, fontFace: FONT_B, color: C.slate, margin: 0
    });
    slide.addText(delta + "  " + pct, {
      x: 2.8, y: y + 0.07, w: 1.85, h: 0.3,
      fontSize: 11, fontFace: FONT_B, bold: true, color: "065F46", margin: 0
    });
    slide.addText(note, {
      x: 0.45, y: y + 0.46, w: 4.2, h: 0.3,
      fontSize: 9.5, fontFace: FONT_B, color: C.slate, italic: true, margin: 0
    });
  });

  const losers = [
    { lang: "Go",      from: 7,  to: 16, delta: "-9 spots",  pct: "-1.49 pp", note: "Sharpest absolute drop; possible Rust displacement" },
    { lang: "C++",     from: 2,  to: 3,  delta: "-1 spot",   pct: "-2.90 pp", note: "Largest percentage decline in any top-5 language" },
    { lang: "Java",    from: 3,  to: 4,  delta: "-1 spot",   pct: "-2.37 pp", note: "Multi-year downtrend from 25%+ peak" },
    { lang: "PHP",     from: 13, to: 18, delta: "-5 spots",  pct: "-0.25 pp", note: "Steady erosion as Python dominates web backends" },
  ];

  losers.forEach(({ lang, from, to, delta, pct, note }, i) => {
    const y = 1.35 + i * 0.95;
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 5.22, y, w: 4.5, h: 0.85,
      fill: { color: "FEE2E2" }, line: { color: "FCA5A5" }
    });
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 5.22, y, w: 0.09, h: 0.85,
      fill: { color: C.red }, line: { color: C.red }
    });
    slide.addText(lang, {
      x: 5.39, y: y + 0.07, w: 1.4, h: 0.3,
      fontSize: 13, fontFace: FONT_H, bold: true, color: "7F1D1D", margin: 0
    });
    slide.addText(`${from} → ${to}`, {
      x: 6.84, y: y + 0.07, w: 0.85, h: 0.3,
      fontSize: 11, fontFace: FONT_B, color: C.slate, margin: 0
    });
    slide.addText(delta + "  " + pct, {
      x: 7.74, y: y + 0.07, w: 1.85, h: 0.3,
      fontSize: 11, fontFace: FONT_B, bold: true, color: "991B1B", margin: 0
    });
    slide.addText(note, {
      x: 5.39, y: y + 0.46, w: 4.2, h: 0.3,
      fontSize: 9.5, fontFace: FONT_B, color: C.slate, italic: true, margin: 0
    });
  });

  // Solid divider (not dashed)
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 4.88, y: 0.86, w: 0.24, h: 4.52,
    fill: { color: "CBD5E1" }, line: { color: "CBD5E1" }
  });

  // Key insight below cards
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.28, y: 5.18, w: 9.44, h: 0.24,
    fill: { color: "E0F2FE" }, line: { color: "BAE6FD" }
  });
  slide.addText(
    "Key: Go's -9-rank freefall is the steepest of any top-20 language. Legacy languages (Perl, R) defy expectations by climbing into the top 12.",
    {
      x: 0.38, y: 5.18, w: 9.24, h: 0.24,
      fontSize: 8.5, fontFace: FONT_B, color: C.navy, margin: 0, valign: "middle"
    }
  );

  footer(slide);
}

// ═══════════════════════════════════════════════════════════════════════════
// SLIDE 4 — HISTORICAL CONTEXT
// ═══════════════════════════════════════════════════════════════════════════
{
  const slide = pres.addSlide();
  slide.background = { color: C.light };
  header(slide, "From Lisp at #2 in 1986 to Python at #1 in 2026: Four Decades of Language Rankings");

  const years = ["1986","1991","1996","2001","2006","2011","2016","2021","2026"];
  const tableData = [
    [
      { text: "Language", options: { bold: true, color: C.white, fill: { color: C.navy }, fontSize: 8, align: "left" } },
      ...years.map(y => ({ text: y, options: { bold: true, color: C.white, fill: { color: C.navy }, fontSize: 8, align: "center" } }))
    ]
  ];

  // Go and Ada: no parenthetical to avoid cell overflow — just the current rank
  const histRows = [
    ["Python",     "-","-","17","26","8","7","5","3","1"],
    ["C",          "1","1","1","1","2","2","2","1","2"],
    ["C++",        "9","2","2","2","3","3","3","4","3"],
    ["Java",       "-","-","31","3","1","1","1","2","4"],
    ["C#",         "-","-","-","11","7","5","4","5","5"],
    ["JavaScript", "-","-","33","8","10","10","8","7","6"],
    ["Go",         "-","-","-","-","-","16","60","11","16"],
    ["Ada",        "3","10","6","18","16","22","25","36","19"],
    ["Lisp",       "2","4","8","19","14","13","26","34","26"],
  ];

  histRows.forEach(([lang, ...vals], i) => {
    const rowFill = i % 2 === 0 ? C.white : "EFF6FF";
    const cells = vals.map((v, j) => {
      let fill = { color: rowFill };
      let col = C.label;
      let bold = false;
      if (lang === "Python" && j === 8) { fill = { color: "D1FAE5" }; col = "065F46"; bold = true; }
      if (lang === "C"      && j === 8) { fill = { color: "DBEAFE" }; col = C.mid;   bold = true; }
      if (lang === "Lisp"   && j === 0) { fill = { color: "FEE2E2" }; col = "991B1B"; bold = true; }
      if (v === "-") col = C.muted;
      return { text: v, options: { fontSize: 8, align: "center", fill, color: col, bold } };
    });
    tableData.push([
      { text: lang, options: { fontSize: 8, align: "left", fill: { color: rowFill }, color: C.label, bold: ["Python","C"].includes(lang) } },
      ...cells
    ]);
  });

  slide.addTable(tableData, {
    x: 0.28, y: 0.86, w: 5.8,
    colW: [1.1, 0.52, 0.52, 0.52, 0.52, 0.52, 0.52, 0.52, 0.52, 0.52],
    border: { pt: 0.5, color: "CBD5E1" },
    rowH: 0.38,
  });

  // Table footnote — with enough space from footer
  slide.addText("Go & Ada: 2026 column shows current rank. Go was #60 in 2016, now #16. Ada re-entered top 20 at #19.", {
    x: 0.28, y: 5.2, w: 5.8, h: 0.22,
    fontSize: 7.5, fontFace: FONT_B, color: C.slate, italic: true, margin: 0
  });

  // Right panel — insight cards (same design, consistent color approach)
  const insights = [
    { color: C.teal,  title: "Python: 0 to #1 in 25 years", body: "Unranked before 1991. Entered top-30 by 2001. Reached #1 after 2018. A uniquely modern ascent." },
    { color: C.red,   title: "Java's long decline",           body: "Dominated at 25%+ from 2005–2018. Now below 8% — the steepest fall of any top-4 language." },
    { color: C.gold,  title: "C: the only constant",          body: "The sole language in the top 2 across all nine measurement points from 1986 to 2026." },
    { color: C.slate, title: "Lisp & Ada: four-decade fall",  body: "Lisp was #2 in 1986, now #26. Ada was #3 in 1986, now #19. Language dominance rarely persists." },
  ];

  insights.forEach(({ color, title, body }, i) => {
    const y = 0.88 + i * 1.1;
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 6.28, y, w: 3.44, h: 0.98,
      fill: { color: C.white }, line: { color: "E2E8F0" },
      shadow: { type: "outer", blur: 4, offset: 1, angle: 135, color: "000000", opacity: 0.07 }
    });
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 6.28, y, w: 0.09, h: 0.98,
      fill: { color: color }, line: { color: color }
    });
    slide.addText(title, {
      x: 6.45, y: y + 0.08, w: 3.15, h: 0.3,
      fontSize: 10.5, fontFace: FONT_H, bold: true, color: C.dark, margin: 0
    });
    slide.addText(body, {
      x: 6.45, y: y + 0.4, w: 3.15, h: 0.5,
      fontSize: 9, fontFace: FONT_B, color: C.label, margin: 0
    });
  });

  footer(slide);
}

// ═══════════════════════════════════════════════════════════════════════════
// SLIDE 5 — HALL OF FAME
// ═══════════════════════════════════════════════════════════════════════════
{
  const slide = pres.addSlide();
  slide.background = { color: C.dark };

  // Top gold strip
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.05,
    fill: { color: C.gold }, line: { color: C.gold }
  });

  slide.addText("Python Wins Language of the Year 6 Times — More Than Any Other Language", {
    x: 0.4, y: 0.12, w: 9.2, h: 0.65,
    fontSize: 17, fontFace: FONT_H, bold: true,
    color: C.white, valign: "middle", margin: 0
  });

  // Subtitle
  slide.addText("TIOBE \"Language of the Year\" — awarded to the language with the largest annual rating gain", {
    x: 0.4, y: 0.74, w: 9.2, h: 0.28,
    fontSize: 10, fontFace: FONT_B, color: C.muted, margin: 0
  });

  const awards = [
    { year: "2025", lang: "C#",     color: "818CF8", note: "2nd title in 3 years" },
    { year: "2024", lang: "Python", color: C.teal,   note: "6th all-time win" },
    { year: "2023", lang: "C#",     color: "818CF8", note: ".NET ecosystem growth" },
    { year: "2022", lang: "C++",    color: "FB923C", note: "Systems surge" },
    { year: "2021", lang: "Python", color: C.teal,   note: "5th all-time win" },
    { year: "2020", lang: "Python", color: C.teal,   note: "4th all-time win" },
    { year: "2019", lang: "C",      color: "38BDF8", note: "Steady resurgence" },
    { year: "2018", lang: "Python", color: C.teal,   note: "3rd all-time win" },
    { year: "2016", lang: "Go",     color: "A3E635", note: "Preceded 2026 decline" },
  ];

  const cols = 3;
  const cardW = 2.9, cardH = 1.1;
  const startX = 0.35, startY = 1.1, gapX = 0.225, gapY = 0.16;

  awards.forEach(({ year, lang, color, note }, i) => {
    const col = i % cols;
    const row = Math.floor(i / cols);
    const x = startX + col * (cardW + gapX);
    const y = startY + row * (cardH + gapY);

    slide.addShape(pres.shapes.RECTANGLE, {
      x, y, w: cardW, h: cardH,
      fill: { color: "1B2E47" }, line: { color: "2D4A6E" }
    });
    slide.addShape(pres.shapes.RECTANGLE, {
      x, y, w: cardW, h: 0.055,
      fill: { color: color }, line: { color: color }
    });
    slide.addText(year, {
      x: x + 0.18, y: y + 0.1, w: 0.8, h: 0.3,
      fontSize: 12, fontFace: FONT_H, color: C.muted, margin: 0
    });
    slide.addText(lang, {
      x: x + 0.18, y: y + 0.4, w: cardW - 0.3, h: 0.42,
      fontSize: 20, fontFace: FONT_H, bold: true, color: color, margin: 0
    });
    slide.addText(note, {
      x: x + 0.18, y: y + 0.83, w: cardW - 0.3, h: 0.22,
      fontSize: 9, fontFace: FONT_B, color: "7FB3D3", italic: true, margin: 0
    });
  });

  // Python stat footer bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.35, y: 4.86, w: 9.3, h: 0.3,
    fill: { color: "0D2236" }, line: { color: "1E3A55" }
  });
  slide.addText(
    "Python: 6 wins  (2007, 2010, 2018, 2020, 2021, 2024) — most of any language.   C#: 2 recent wins (2023, 2025).   Go won in 2016; now ranked 16th.",
    {
      x: 0.5, y: 4.86, w: 9.1, h: 0.3,
      fontSize: 9, fontFace: FONT_B, color: "A8BFDA",
      valign: "middle", margin: 0
    }
  );

  // Note on 2017
  slide.addText("Note: 2017 Language of the Year winner not available in source data.", {
    x: 0.35, y: 5.22, w: 9, h: 0.2,
    fontSize: 8, fontFace: FONT_B, color: C.slate, italic: true, margin: 0
  });

  // Footer
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 5.45, w: 10, h: 0.175,
    fill: { color: "080E18" }, line: { color: "080E18" }
  });
  slide.addText("Source: TIOBE Programming Community Index, March 2026  |  tiobe.com", {
    x: 0.35, y: 5.45, w: 9.3, h: 0.175,
    fontSize: 8, fontFace: FONT_B, color: "4A7099",
    valign: "middle", margin: 0
  });
}

