      x, y, w, h: cardH,
      fill: { color: "132035" }, line: { color: "1E3A55" }
    });
    slide.addShape(pres.shapes.RECTANGLE, {
      x, y, w: 0.09, h: cardH,
      fill: { color: color }, line: { color: color }
    });
    slide.addText(num, {
      x: x + 0.18, y: y + 0.06, w: 0.45, h: 0.32,
      fontSize: 13, fontFace: FONT_H, bold: true, color: color, margin: 0
    });
    slide.addText(title, {
      x: x + 0.68, y: y + 0.06, w: w - 0.82, h: 0.3,
      fontSize: 11, fontFace: FONT_H, bold: true, color: C.white, margin: 0
    });
    slide.addText(body, {
      x: x + 0.68, y: y + 0.42, w: w - 0.82, h: 0.44,
      fontSize: 9.5, fontFace: FONT_B, color: "A8BFDA", margin: 0
    });
  });

  // Disclaimer bar — right below cards
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 4.06, w: 10, h: 0.58,
    fill: { color: "0A1628" }, line: { color: "0A1628" }
  });
  slide.addText(
    "Data: TIOBE Index March 2026  ·  Next update: April 2026\n" +
