{
  const slide = pres.addSlide();
  slide.background = { color: C.light };
  header(slide, "Python Holds #1 at 21.25% but C Surges to #2 with the Largest Gain");

  const tableRows = [
    [
      { text: "Mar 2026", options: { bold: true, color: C.white, fill: { color: C.navy }, fontSize: 8.5, align: "center" } },
      { text: "Mar 2025", options: { bold: true, color: C.white, fill: { color: C.navy }, fontSize: 8.5, align: "center" } },
      { text: "Language", options: { bold: true, color: C.white, fill: { color: C.navy }, fontSize: 8.5, align: "left" } },
      { text: "Rating",   options: { bold: true, color: C.white, fill: { color: C.navy }, fontSize: 8.5, align: "center" } },
      { text: "YoY (pp)", options: { bold: true, color: C.white, fill: { color: C.navy }, fontSize: 8.5, align: "center" } },
    ]
  ];

  const rows = [
    [1, 1,  "Python",               "21.25%", "-2.59"],
    [2, 4,  "C",                    "11.55%", "+2.02"],
    [3, 2,  "C++",                  "8.18%",  "-2.90"],
    [4, 3,  "Java",                 "7.99%",  "-2.37"],
    [5, 5,  "C#",                   "6.36%",  "+1.49"],
    [6, 6,  "JavaScript",           "3.45%",  "-0.01"],
    [7, 9,  "Visual Basic",         "2.50%",  "-0.02"],
    [8, 8,  "SQL",                  "2.00%",  "-0.57"],
    [9, 16, "R",                    "1.88%",  "+0.94"],
    [10,10, "Delphi/Obj. Pascal",   "1.80%",  "-0.36"],
    [11,24, "Perl",                 "1.75%",  "+1.05"],
    [12,12, "Scratch",              "1.63%",  "-0.03"],
    [13,11, "Fortran",              "1.45%",  "-0.25"],
    [14,14, "Rust",                 "1.31%",  "+0.09"],
    [15,15, "MATLAB",               "1.29%",  "+0.31"],
    [16, 7, "Go",                   "1.29%",  "-1.49"],
    [17,17, "Assembly",             "1.29%",  "+0.42"],
    [18,13, "PHP",                  "1.23%",  "-0.25"],
    [19,18, "Ada",                  "1.10%",  "+0.25"],
    [20,26, "Swift",                "1.04%",  "+0.44"],
  ];

  for (const [cur, prev, lang, rating, yoy] of rows) {
    const val = parseFloat(yoy);
    const isGainer = val > 0;
    const isLoser  = val < -0.1;
    const yoyColor = isGainer ? "065F46" : (isLoser ? "991B1B" : C.slate);
    const rowFill  = cur % 2 === 0 ? "DBEAFE" : C.white;
    const bigGainer = isGainer && val >= 0.9;
    const bigLoser  = isLoser  && val <= -1.0;
    const langFill  = bigGainer ? "D1FAE5" : bigLoser ? "FEE2E2" : rowFill;

    tableRows.push([
      { text: String(cur),  options: { fontSize: 8.5, align: "center", fill: { color: rowFill }, color: C.label, bold: cur <= 4 } },
      { text: String(prev), options: { fontSize: 8.5, align: "center", fill: { color: rowFill }, color: C.slate } },
      { text: lang,         options: { fontSize: 8.5, align: "left",   fill: { color: langFill }, color: C.label, bold: cur <= 4 } },
      { text: rating,       options: { fontSize: 8.5, align: "center", fill: { color: rowFill }, color: C.label, bold: cur === 1 } },
      { text: (val > 0 ? "+" : "") + yoy, options: { fontSize: 8.5, align: "center", fill: { color: rowFill }, color: yoyColor, bold: bigGainer || bigLoser } },
    ]);
  }

  slide.addTable(tableRows, {
