  });
  slide.addText("GAINERS", {
    x: 0.28, y: 0.86, w: 4.5, h: 0.38,
    fontSize: 12, fontFace: FONT_H, bold: true, color: C.white,
    align: "center", valign: "middle", margin: 0
  });

  // LOSERS header
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.22, y: 0.86, w: 4.5, h: 0.38,
