for (const [cur, prev, lang, rating, yoy] of rows) {
  const val = parseFloat(yoy);
  const isGainer = val > 0;
  const isLoser  = val < -0.1;
  const yoyColor = isGainer ? "065F46" : (isLoser ? "991B1B" : C.slate);
  const rowFill  = cur % 2 === 0 ? "DBEAFE" : C.white;
  const bigGainer = isGainer && val >= 0.9;
  const bigLoser  = isLoser  && val <= -1.0;
  const langFill  = bigGainer ? "D1FAE5" : bigLoser ? "FEE2E2" : rowFill;

  tableRows.push([
    { text: String(cur),  options: { fontSize: 8, align: "center", fill: { color: rowFill }, color: C.label, bold: cur <= 4 } },
    { text: String(prev), options: { fontSize: 8, align: "center", fill: { color: rowFill }, color: C.slate } },
    { text: lang,         options: { fontSize: 8, align: "left",   fill: { color: langFill }, color: C.label, bold: cur <= 4 } },
    { text: rating,       options: { fontSize: 8, align: "center", fill: { color: rowFill }, color: C.label, bold: cur === 1 } },
  { text: (val > 0 ? "+" : "") + yoy, options: { fontSize: 8, align: "center", fill: { color: rowFill }, color: yoyColor, bold: bigGainer || bigLoser } },
  ]);
}

// 21 rows × 0.17" = 3.57" → table ends at 0.86 + 3.57 = 4.43"
slide.addTable(tableRows, {
  x: 0.28, y: 0.86, w: 6.1,
  colW: [0.6, 0.6, 2.0, 0.8, 0.82],
  border: { pt: 0.5, color: "CBD5E1" },
  rowH: 0.17,

